styles:
body {
    font-family: 'Roboto Condensed', sans-serif;
    line-height: 1.6;
    color: #FFFFFF;
    margin: 0;
    padding: 0;
    background-color: #000000;
}
.container {
    max-width: 900px;
    margin: 20px auto;
    padding: 20px 30px;
}
h1, h2, h3, h4 {
    color: #FFFFFF;
    font-weight: 700;
    text-transform: uppercase;
    font-family: 'Roboto Condensed', sans-serif;
}
h1 {
    font-size: 2.5em;
    border-bottom: 3px solid #330000;
    padding-bottom: 15px;
    margin-bottom: 25px;
    text-align: center;
    letter-spacing: 1px;
}
h2 {
    font-size: 1.8em;
    margin-top: 30px;
    border-left: 5px solid #cc0000;
    padding-left: 10px;
}
h3 {
    font-size: 1.3em;
    margin-top: 20px;
    color: #ff3333;
}
h4 {
    font-size: 1.1em;
    margin-top: 15px;
    color: #ffcc00;
}
p {
    margin-bottom: 15px;
    color: #FFFFFF;
}
a {
    color: #ffaa33;
    text-decoration: none;
}
a:hover {
    color: #ffd077;
    text-decoration: underline;
}

/* ----------------------------------------------------------------
   XEM THEM BLOCK
---------------------------------------------------------------- */
div.xem-them {
    display: block;
    box-sizing: border-box;
    width: 100%;
    background-color: #1a1200;
    border-top: 1px solid #7a5500;
    border-right: 1px solid #7a5500;
    border-bottom: 1px solid #7a5500;
    border-left: 4px solid #ffaa33;
    border-radius: 4px;
    padding: 11px 16px;
    margin: 20px 0 24px 0;
    font-family: 'Roboto Condensed', sans-serif;
    font-size: 0.95em;
    font-weight: 700;
    color: #ffaa33;
    letter-spacing: 0.4px;
    text-transform: uppercase;
    line-height: 1.5;
}
div.xem-them a {
    color: #ffcc77;
    text-decoration: none;
    font-weight: 400;
    text-transform: none;
    letter-spacing: 0;
}
div.xem-them a:hover {
    color: #ffe8aa;
    text-decoration: underline;
}

/* --- TABLE --- */
table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
}
table td, table th {
    border: 1px solid #440000;
    padding: 10px 12px;
    color: #ffffff;
    vertical-align: top;
}
table tr:first-child td {
    background-color: #1a0000;
    font-weight: 700;
    color: #ffcc00;
}
table tr:not(:first-child):nth-child(even) td {
    background-color: #0d0d0d;
}

/* ----------------------------------------------------------------
   HIGHLIGHT BLOCK — key facts / inline callouts replacing bullets
---------------------------------------------------------------- */
div.highlight-block {
    background-color: #0d0d0d;
    border: 1px solid #440000;
    border-left: 4px solid #ff3333;
    border-radius: 4px;
    padding: 14px 18px;
    margin: 20px 0;
    color: #e8e8e8;
    font-size: 0.97em;
    line-height: 1.7;
}
div.highlight-block strong {
    color: #ffcc00;
}

/* ----------------------------------------------------------------
   SPEC BLOCK — product spec table card
---------------------------------------------------------------- */
div.spec-block {
    background-color: #0d0d0d;
    border: 1px solid #440000;
    border-left: 4px solid #cc0000;
    border-radius: 4px;
    padding: 18px 20px;
    margin: 20px 0 24px 0;
}
div.spec-block h4 {
    margin-top: 0;
    margin-bottom: 12px;
    color: #ffcc00;
    text-transform: none;
    font-size: 1.05em;
    border-bottom: 1px solid #330000;
    padding-bottom: 10px;
}
table.spec-table {
    width: 100%;
    border-collapse: collapse;
    margin: 0;
}
table.spec-table td {
    border: none;
    border-bottom: 1px solid #220000;
    padding: 8px 6px;
    vertical-align: top;
}
table.spec-table tr:first-child td {
    background-color: transparent;
    font-weight: 400;
    color: #ffffff;
}
table.spec-table tr:not(:first-child):nth-child(even) td {
    background-color: transparent;
}
table.spec-table tr:last-child td {
    border-bottom: none;
}
table.spec-table td:first-child {
    color: #ff8888;
    font-weight: 700;
    width: 38%;
    white-space: nowrap;
}
